  gorsel: `<svg viewBox="0 0 540 150" role="img" aria-label="Periyodik sistemden alınmış iki satır iki sütunluk kesit: üst satırda X ve Y, alt satırda Z ve T"><g stroke="currentColor" stroke-width="2"><rect x="210" y="15" width="60" height="60" fill="none"/><rect x="270" y="15" width="60" height="60" fill="none"/><rect x="210" y="75" width="60" height="60" fill="none"/><rect x="270" y="75" width="60" height="60" fill="none"/></g><g fill="currentColor" font-size="22" font-weight="bold" text-anchor="middle"><text x="240" y="53">X</text><text x="300" y="53">Y</text><text x="240" y="113">Z</text><text x="300" y="113">T</text></g></svg>`,
